const { chromium }=require('playwright');
(async()=>{const b=await chromium.launch({headless:true,args:['--use-gl=swiftshader','--enable-webgl','--ignore-gpu-blocklist']});const p=await b.newPage({viewport:{width:1400,height:900}});const out=[];p.on('pageerror',e=>out.push('PAGEERROR '+e.stack));p.on('console',m=>out.push('CONSOLE '+m.type()+' '+m.text()));await p.goto('http://127.0.0.1:4173/labs/interactive-boards-source/casebook-pro-v3-fashion-lab/index.html',{waitUntil:'domcontentloaded',timeout:30000});await p.waitForTimeout(7000);out.push('SHELL '+!!(await p.$('#esShell')));out.push('FRAMES '+p.frames().length);console.log(out.join('\n'));await b.close();if(!out.some(x=>x.startsWith('PAGEERROR'))&&out.some(x=>x==='SHELL true'))process.exit(0);process.exit(1)})().catch(e=>{console.error(e);process.exit(1)});